var original=UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<VRC.SDK3.Avatars.Components.VRCAvatarDescriptor>(true)).Single(a=>a.name=="MANUKA_lilToon");var avatar=UnityEngine.Object.Instantiate(original.gameObject);var helper=new UnityEngine.GameObject("anus ray probe");var mesh=new UnityEngine.Mesh();
try{
var renderer=avatar.GetComponentsInChildren<UnityEngine.SkinnedMeshRenderer>(true).Single(r=>r.name=="Manuka_body");for(int i=0;i<renderer.sharedMesh.blendShapeCount;i++)if(renderer.sharedMesh.GetBlendShapeName(i).StartsWith("Shrink"))renderer.SetBlendShapeWeight(i,0);renderer.BakeMesh(mesh,true);helper.transform.SetPositionAndRotation(renderer.transform.position,renderer.transform.rotation);helper.transform.localScale=renderer.transform.lossyScale;var col=helper.AddComponent<UnityEngine.MeshCollider>();col.sharedMesh=mesh;UnityEngine.Physics.SyncTransforms();
var hip=avatar.GetComponent<UnityEngine.Animator>().GetBoneTransform(UnityEngine.HumanBodyBones.Hips);var result=new System.Collections.Generic.List<string>{"hips="+hip.position.ToString("F5")};
foreach(float z in new[]{-.08f,-.06f,-.05f,-.04f,-.03f,-.02f,-.01f,0f,.01f,.02f,.03f}){var origin=new UnityEngine.Vector3(hip.position.x,hip.position.y-.4f,z);if(col.Raycast(new UnityEngine.Ray(origin,UnityEngine.Vector3.up),out var hit,.8f))result.Add(z+";pos="+hit.point.ToString("F5")+";normal="+hit.normal.ToString("F5"));else result.Add(z+";miss");}return result;
}finally{UnityEngine.Object.DestroyImmediate(helper);UnityEngine.Object.DestroyImmediate(mesh);UnityEngine.Object.DestroyImmediate(avatar);}
